package main

// Battle servers: the control plane's instance list (dn-dedicated) and the
// stop action, for the dashboard's Battle servers page.

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/gorilla/mux"
	"github.com/sirupsen/logrus"
)

// adminInstanceIDRE: what an instance id may look like before it goes into the
// control plane URL (ids are generated by dn-dedicated; nothing else passes).
var adminInstanceIDRE = regexp.MustCompile(`^[A-Za-z0-9._-]{1,80}$`)

type adminInstance struct {
	ID        string   `json:"id"`
	Port      int      `json:"port"`
	GameMode  string   `json:"game_mode"`
	Map       string   `json:"map"`
	MatchID   string   `json:"match_id"`
	Players   []string `json:"players"`
	Ready     bool     `json:"ready"`
	Running   bool     `json:"running"`
	StartedAt string   `json:"started_at"`
	PID       int      `json:"pid"`
	// Filled in here:
	PlayerNames []string `json:"player_names"`
	Crashed     string   `json:"crashed,omitempty"` // from the battle log
	// Filled in by adminAPIInstances (not by the overview, which only counts):
	MatchRef string `json:"match_ref,omitempty"` // matches.id of the match it hosts
	Log      string `json:"log,omitempty"`       // its battle log's file name
}

func controlPlaneInstances() ([]adminInstance, error) {
	req, err := http.NewRequest(http.MethodGet, strings.TrimRight(adminDash.controlPlaneURL, "/")+"/instances", nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("X-Internal-Key", adminDash.internalKey)
	client := &http.Client{Timeout: 5 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()
	var body struct {
		Instances []adminInstance `json:"instances"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		return nil, err
	}
	for i := range body.Instances {
		for _, pid := range body.Instances[i].Players {
			body.Instances[i].PlayerNames = append(body.Instances[i].PlayerNames, adminPlayerName(pid))
		}
		body.Instances[i].Crashed = battleLogCrash(body.Instances[i].StartedAt, body.Instances[i].Port)
	}
	return body.Instances, nil
}

func adminAPIInstances(w http.ResponseWriter, _ *http.Request) {
	list, err := controlPlaneInstances()
	if err != nil {
		writeAdminJSON(w, map[string]any{"error": "control plane unreachable: " + err.Error(), "instances": []any{}})
		return
	}
	// One lookup per instance, none while a result set is open (one connection).
	if database := currentMmogPlayerStateDB(); database != nil {
		for i := range list {
			_ = database.QueryRow(`SELECT id FROM matches WHERE (? <> '' AND (id=? OR battle_match_id=?)) OR (? <> '' AND instance_id=?)
				ORDER BY created_at DESC LIMIT 1`, list[i].MatchID, list[i].MatchID, list[i].MatchID, list[i].ID, list[i].ID).Scan(&list[i].MatchRef)
		}
	}
	for i := range list {
		list[i].Log = instanceLogName(list[i].StartedAt, list[i].Port)
	}
	writeAdminJSON(w, map[string]any{"instances": list})
}

// instanceLogName is the battle log file of a running instance (the name
// battleLogCrash reads), or "" if that file does not exist.
func instanceLogName(startedAt string, port int) string {
	t, err := time.Parse(time.RFC3339, startedAt)
	if err != nil {
		return ""
	}
	name := fmt.Sprintf("battle-%s-port%d.log", t.Local().Format("20060102-150405"), port)
	if _, err := os.Stat(filepath.Join("run", "battle-logs", name)); err != nil {
		return ""
	}
	return name
}

func adminAPIStopInstance(w http.ResponseWriter, r *http.Request) {
	id := mux.Vars(r)["id"]
	if !adminInstanceIDRE.MatchString(id) {
		writeAdminError(w, http.StatusBadRequest, "bad instance id")
		return
	}
	req, err := http.NewRequest(http.MethodDelete, strings.TrimRight(adminDash.controlPlaneURL, "/")+"/instances/"+id, nil)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	req.Header.Set("X-Internal-Key", adminDash.internalKey)
	resp, err := (&http.Client{Timeout: 15 * time.Second}).Do(req)
	if err != nil {
		http.Error(w, "control plane unreachable", http.StatusBadGateway)
		return
	}
	_ = resp.Body.Close()
	logrus.WithFields(logrus.Fields{"instance": id, "status": resp.StatusCode, "by": r.RemoteAddr}).
		Warn("admin dashboard: battle server stopped")
	adminAudit(currentMmogPlayerStateDB(), r, "stop instance", id, map[string]any{"status": resp.StatusCode})
	if resp.StatusCode >= 400 {
		writeAdminError(w, http.StatusBadGateway, fmt.Sprintf("the control plane answered %d", resp.StatusCode))
		return
	}
	writeAdminJSON(w, map[string]any{"status": resp.StatusCode})
}

// battleLogCrash reports the crash kind a running instance's battle log shows,
// if any: a crashed host can stay "running" (Wine's debugger holds it).
func battleLogCrash(startedAt string, port int) string {
	t, err := time.Parse(time.RFC3339, startedAt)
	if err != nil {
		return ""
	}
	path := filepath.Join("run", "battle-logs", fmt.Sprintf("battle-%s-port%d.log", t.Local().Format("20060102-150405"), port))
	tail := tailFile(path, 64*1024)
	switch {
	case strings.Contains(tail, "EXCEPTION_STACK_OVERFLOW"):
		return "stack overflow"
	case strings.Contains(tail, "Unhandled Exception"), strings.Contains(tail, "Unhandled page fault"):
		return "access violation"
	}
	return ""
}
